def kthCharacter(s: str, k: int) -> str:
    for word in s.split(' '):
        L = len(word)
        size = L * (L + 1) // 2           # expanded length of this word

        if k < size:
            # the answer is inside this word: character i takes i + 1 slots
            used = 0
            for i, ch in enumerate(word):
                used += i + 1
                if k < used:
                    return ch

        k -= size                          # skip the whole expanded word
        if k == 0:
            return ' '                     # the single space after this word
        k -= 1                             # skip that space

    return ''                              # unreachable for a valid k
